#!/usr/bin/env pwsh
$basedir=Split-Path $MyInvocation.MyCommand.Definition -Parent

$exe=""
$pathsep=":"
$env_node_path=$env:NODE_PATH
$new_node_path="E:\ai\项目\大肥鱼\qqbot\plugins\dsh-nekowhale-stickers-main\lib\node_modules;E:\ai\项目\大肥鱼\qqbot\plugins\dsh-nekowhale-stickers-main\node_modules;E:\ai\项目\大肥鱼\qqbot\plugins\node_modules;E:\ai\项目\大肥鱼\qqbot\node_modules;E:\ai\项目\大肥鱼\node_modules;E:\ai\项目\node_modules;E:\ai\node_modules;E:\node_modules;E:\ai\项目\大肥鱼\qqbot\.dsh\profiles\qqbot\node_modules\.pnpm\node_modules"
if ($PSVersionTable.PSVersion -lt "6.0" -or $IsWindows) {
  # Fix case when both the Windows and Linux builds of Node
  # are installed in the same directory
  $exe=".exe"
  $pathsep=";"
} else {
  $new_node_path="/mnt/e/ai/项目/大肥鱼/qqbot/plugins/dsh-nekowhale-stickers-main/lib/node_modules:/mnt/e/ai/项目/大肥鱼/qqbot/plugins/dsh-nekowhale-stickers-main/node_modules:/mnt/e/ai/项目/大肥鱼/qqbot/plugins/node_modules:/mnt/e/ai/项目/大肥鱼/qqbot/node_modules:/mnt/e/ai/项目/大肥鱼/node_modules:/mnt/e/ai/项目/node_modules:/mnt/e/ai/node_modules:/mnt/e/node_modules:/mnt/e/ai/项目/大肥鱼/qqbot/.dsh/profiles/qqbot/node_modules/.pnpm/node_modules"
}
if ([string]::IsNullOrEmpty($env_node_path)) {
  $env:NODE_PATH=$new_node_path
} else {
  $env:NODE_PATH="$new_node_path$pathsep$env_node_path"
}

$ret=0
if (Test-Path "$basedir/node$exe") {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "$basedir/node$exe"  "$basedir/../dsh-nekowhale-stickers/lib/cli.js" $args
  } else {
    & "$basedir/node$exe"  "$basedir/../dsh-nekowhale-stickers/lib/cli.js" $args
  }
  $ret=$LASTEXITCODE
} else {
  # Support pipeline input
  if ($MyInvocation.ExpectingInput) {
    $input | & "node$exe"  "$basedir/../dsh-nekowhale-stickers/lib/cli.js" $args
  } else {
    & "node$exe"  "$basedir/../dsh-nekowhale-stickers/lib/cli.js" $args
  }
  $ret=$LASTEXITCODE
}
$env:NODE_PATH=$env_node_path
exit $ret
